"""Власний ШІ-помічник підтримки NeonDrop — працює повністю всередині сайту, без жодних зовнішніх API.
Як працює: розпізнає намір (UA/RU) за ключовими словами, дивиться дані акаунта гравця (баланс, платежі, трейд-посилання),
відповідає з бази знань, для дій (підтвердити платіж, змінити нік, скинути трейд-посилання) ПРОСИТЬ ДОЗВІЛ адміністратора,
а питання, яких не знає, передає людині й вчиться на відповідях адміністратора (таблиця faq)."""
import re


def norm(t):
    return re.sub(r"[^\w' ]+", " ", (t or "").lower().replace("ё", "е").replace("’", "'"))


def words(t): return norm(t).split()
UA_WORDS = {"як", "що", "чи", "мені", "мене", "мій", "моя", "мої", "моє", "та", "але", "також", "вже", "ще", "дуже", "треба", "потрібно", "будь", "ласка", "дякую", "привіт", "вітаю", "який", "яка", "які", "коли", "чому", "куди", "звідки", "скільки", "можна", "хочу", "допоможіть"}
def lang(t):
    tl = (t or "").lower()
    return "ua" if re.search(r"[іїєґ]", tl) or any(w in UA_WORDS for w in re.findall(r"\w+", tl)) else "ru"
def T(L, ua, ru): return ua if L == "ua" else ru
def has(ws, *pre): return any(w.startswith(p) for w in ws for p in pre)
def exact(ws, *x): return any(w in x for w in ws)
def stems(t): return {w[:5] for w in words(t) if len(w) > 2}


def similar(a, b):  # схожість двох фраз (0..1) за коренями слів
    A, B = stems(a), stems(b)
    return len(A & B) / len(A | B) if A and B else 0.0


def _min(m): return f"{int(m)} хв"


def answer(text, ctx, faq=()):
    """text — повідомлення гравця; ctx — дані акаунта; faq — [(питання, відповідь)] від адміністратора.
    Повертає {"kind": "reply" | "human" | "ask" | "act", "text": ..., "action": {...}}"""
    L, ws, tl = lang(text), words(text), norm(text)
    R = lambda ua, ru, **k: {"kind": "reply", "text": T(L, ua, ru), **k}
    rate = ctx.get("rate", 2.4)
    if not ws: return R("Напишіть, будь ласка, ваше питання.", "Напишите, пожалуйста, ваш вопрос.")
    # 1. людина / скарги / бан — одразу адміністрації
    if has(ws, "людин", "человек", "оператор", "менеджер", "адмін", "админ", "живий", "живой", "спеціаліст", "специалист", "підтримк", "поддержк") and not has(ws, "ваш"):
        return {"kind": "human", "text": T(L, "Передаю ваше звернення адміністрації — відповімо тут, у чаті.", "Передаю ваше обращение администрации — ответим здесь, в чате.")}
    if has(ws, "повернут", "верните", "вернуть", "возврат", "обман", "скам", "scam", "кинули", "кинул", "шахр", "мошен", "развод", "украл", "вкрал"):
        return {"kind": "human", "text": T(L, "Розумію, що ситуація неприємна. Передаю її адміністрації для перевірки — зачекайте на відповідь тут.", "Понимаю, что ситуация неприятная. Передаю её администрации на проверку — ожидайте ответ здесь.")}
    if has(ws, "бан", "заблок", "блок") and not has(ws, "блокчейн"):
        return {"kind": "human", "text": T(L, "Питання блокування вирішує тільки адміністрація. Передаю їй ваше звернення.", "Вопрос блокировки решает только администрация. Передаю ей ваше обращение.")}
    # 2. навчені відповіді адміністратора мають пріоритет
    best = max(((similar(text, q), a) for q, a in faq), default=(0, ""), key=lambda x: x[0])
    if best[0] >= 0.7: return {"kind": "reply", "text": best[1]}
    # 3. дії, що потребують дозволу адміністратора
    if has(ws, "трейд", "trade", "обмін", "обмен", "посилан", "ссылк") and has(ws, "скин", "сброс", "очист", "видал", "удал", "стер", "стёр", "зміни", "измени") and not has(ws, "скін", "скинь") or (has(ws, "трейд", "trade") and has(ws, "скиньте", "сбросьте", "очистіть", "очистите", "видаліть", "удалите")):
        return {"kind": "act", "text": T(L, "Прошу адміністрацію скинути ваше трейд-посилання — після її дозволу воно буде очищене, і ви зможете вказати нове в «Профіль».", "Прошу администрацию сбросить вашу трейд-ссылку — после её разрешения она будет очищена, и вы сможете указать новую в «Профиль»."),
                "action": {"action": "clear_trade_url", "reason": "Гравець просить скинути трейд-посилання"}}
    m = re.search(r"(?:нік|ник|nick|ім'я|имя)\s*(?:на|=|:)?\s*[\"«']?([^\s\"»',.!?]{2,20}(?: [^\s\"»',.!?]{1,10})?)", text or "", re.I)
    if m and has(ws, "змін", "измен", "постав", "хочу", "поменя", "помін", "переймен", "переимен", "change"):
        nick = m.group(1).strip()
        return {"kind": "act", "text": T(L, f"Прошу адміністрацію змінити ваш нік на «{nick}» — напишу, коли вона відповість.", f"Прошу администрацию изменить ваш ник на «{nick}» — напишу, когда она ответит."), "action": {"action": "set_nick", "text": nick, "reason": f"Гравець просить змінити нік на «{nick}»"}}
    dep_strong = has(ws, "поповн", "пополн", "платіж", "платеж", "оплат", "депозит", "зарахув", "зачисл")
    deposit = dep_strong or has(ws, "кошти", "деньги", "гроші")
    waiting = exact(ws, "не", "ні", "нет") or has(ws, "нема", "чека", "жду", "довго", "долго", "зависл", "пропал", "зник", "дошл", "прийшл", "пришл")
    if deposit and waiting:
        deps = ctx.get("deps", [])
        pend = [d for d in deps if d["status"] == "pending"]
        if pend:
            d = pend[0]
            if d["age"] >= 10:
                return {"kind": "act", "text": T(L, f"Бачу вашу заявку #{d['id']} на {d['uah']:.0f} грн — вона ще очікує підтвердження. Передаю адміністрації на перевірку платежу, зачекайте на рішення.", f"Вижу вашу заявку #{d['id']} на {d['uah']:.0f} грн — она ещё ожидает подтверждения. Передаю администрации на проверку платежа, ожидайте решения."),
                        "action": {"action": "confirm_deposit", "deposit_id": d["id"], "reason": f"Гравець каже, що оплатив заявку #{d['id']} на {d['uah']:.0f} UAH (створена {_min(d['age'])} тому). Перевірте надходження на картку."}}
            return R(f"Ваша заявка #{d['id']} на {d['uah']:.0f} грн створена {_min(d['age'])} тому й очікує підтвердження адміністратором. Зазвичай це займає до кількох годин. Якщо за 10+ хвилин нічого не зміниться — напишіть мені ще раз, я передам запит адміністрації.",
                     f"Ваша заявка #{d['id']} на {d['uah']:.0f} грн создана {_min(d['age'])} назад и ожидает подтверждения администратором. Обычно это занимает до нескольких часов. Если через 10+ минут ничего не изменится — напишите мне ещё раз, я передам запрос администрации.")
        if deps and deps[0]["status"] == "paid": return R(f"Останній платіж #{deps[0]['id']} на {deps[0]['uah']:.0f} грн уже зараховано. Ваш баланс: {ctx.get('balance', 0):.0f} монет.", f"Последний платёж #{deps[0]['id']} на {deps[0]['uah']:.0f} грн уже зачислен. Ваш баланс: {ctx.get('balance', 0):.0f} монет.")
        return R("Активних заявок на поповнення не знайдено. Створіть заявку кнопкою «Поповнити» й оплатіть за реквізитами, після цього адміністратор її підтвердить.", "Активных заявок на пополнение не найдено. Создайте заявку кнопкой «Поповнити» и оплатите по реквизитам, после этого администратор её подтвердит.")
    if has(ws, "вхід", "вход", "войти", "увійти", "вилет", "вылет", "слета", "слітає") or (has(ws, "акаунт", "аккаунт", "профіль", "профиль", "дані", "данные", "баланс", "інвентар", "инвентарь") and (has(ws, "зник", "пропал", "скинул", "обнул", "сброс", "стер") or exact(ws, "нема", "нет"))):
        return {"kind": "human", "text": T(L, f"Вибачте за незручності! Передаю адміністрації, щоб перевірили ваш акаунт (ID {ctx.get('id')}) — якщо дані зникли через технічні роботи, їх можна відновити.", f"Извините за неудобства! Передаю администрации, чтобы проверили ваш аккаунт (ID {ctx.get('id')}) — если данные пропали из-за технических работ, их можно восстановить.")}
    # 4. довідкові відповіді
    if not dep_strong and (has(ws, "баланс") or "скільки монет" in tl or "сколько монет" in tl or "скільки в мене" in tl or "сколько у меня" in tl):
        return R(f"Ваш баланс: {ctx.get('balance', 0):.0f} монет. Предметів в інвентарі: {ctx.get('inv', 0)}.", f"Ваш баланс: {ctx.get('balance', 0):.0f} монет. Предметов в инвентаре: {ctx.get('inv', 0)}.")
    if has(ws, "вивест", "вивід", "вывест", "вывод", "вивод", "забрат", "надіслат", "отправит", "передат", "передать"):
        if not ctx.get("trade"): return R("Щоб вивести скін, спершу вкажіть трейд-посилання Steam у розділі «Профіль» (воно ще не заповнене), потім у «Інвентар» натисніть «Вивести» біля предмета.", "Чтобы вывести скин, сначала укажите трейд-ссылку Steam в разделе «Профіль» (она ещё не заполнена), затем в «Інвентар» нажмите «Вивести» у предмета.")
        extra = T(L, f" У черзі на вивід зараз {ctx['wd']} ваших заявок." if ctx.get("wd") else "", f" В очереди на вывод сейчас {ctx['wd']} ваших заявок." if ctx.get("wd") else "")
        return R("Відкрийте «Інвентар» → «Вивести» біля потрібного предмета. Виводи обробляє адміністратор вручну, зазвичай до кількох годин; предмет прийде трейдом у Steam." + extra, "Откройте «Інвентар» → «Вивести» у нужного предмета. Выводы обрабатывает администратор вручную, обычно до нескольких часов; предмет придёт трейдом в Steam." + extra)
    if has(ws, "трейд", "trade", "обмін", "обмен") or (has(ws, "посилан", "ссылк") and not deposit):
        return R("Трейд-посилання вказується в «Профіль» → «Трейд-посилання Steam». Знайти його можна в Steam: Інвентар → Пропозиції обміну → «Хто може надсилати мені пропозиції обміну» → Трейд-посилання. Профіль Steam і інвентар мають бути відкритими.", "Трейд-ссылка указывается в «Профіль» → «Трейд-посилання Steam». Найти её можно в Steam: Инвентарь → Предложения обмена → «Кто может отправлять мне предложения обмена» → Ссылка. Профиль Steam и инвентарь должны быть открыты.")
    if has(ws, "промокод", "промо", "promo", "купон", "бонус"):
        return R("Промокод вводиться у вікні «Поповнити» у полі «Промокод» — він додає бонус у % до монет за це поповнення. Кожен промокод діє один раз на акаунт. Актуальні коди оголошує адміністрація.", "Промокод вводится в окне «Поповнити» в поле «Промокод» — он добавляет бонус в % к монетам за это пополнение. Каждый промокод действует один раз на аккаунт. Актуальные коды объявляет администрация.")
    if deposit or has(ws, "карт", "внест"):
        return R(f"Натисніть «Поповнити» (угорі справа) → «Картка UAH», вкажіть суму від 50 до 50 000 грн і, за бажанням, промокод. 1 грн = {rate:g} монет. Оплатіть за реквізитами — адміністратор підтвердить заявку вручну, і монети зʼявляться на балансі.", f"Нажмите «Поповнити» (вверху справа) → «Картка UAH», укажите сумму от 50 до 50 000 грн и, по желанию, промокод. 1 грн = {rate:g} монет. Оплатите по реквизитам — администратор подтвердит заявку вручную, и монеты появятся на балансе.")
    if has(ws, "прода", "продат", "sell"):
        return R("Продати скін можна в «Інвентар» (кнопка «Продати» чи «Продати все»), а одразу після дропу — кнопкою «Продати за…». Ви отримуєте його повну вартість у монетах.", "Продать скин можно в «Інвентар» (кнопка «Продати» или «Продати все»), а сразу после дропа — кнопкой «Продати за…». Вы получаете его полную стоимость в монетах.")
    if has(ws, "апгрейд", "upgrade", "апгр", "множ"):
        return R("Апгрейд: оберіть свій скін, потім бажаний приз або бажаний шанс (до 75%). Шанс = 95% × ціна вашого скіна ÷ ціна призу. Є швидка й повільна крутка. Іноді зʼявляється NeonDrop — неоновий сектор, що дає приз у 2–3 рази більший.", "Апгрейд: выберите свой скин, затем желаемый приз или желаемый шанс (до 75%). Шанс = 95% × цена вашего скина ÷ цена приза. Есть быстрая и медленная крутка. Иногда появляется NeonDrop — неоновый сектор, дающий приз в 2–3 раза больше.")
    if has(ws, "кейс", "case", "відкрит", "открыт", "випад", "выпад", "дроп", "drop", "шанс"):
        return R("Кейси відкриваються на сторінці «Кейси»: можна відкривати 1–5 за раз, є режим «Швидко». Точні шанси не публікуються: чим дорожчий скін, тим рідше він випадає, а ціна кейса завжди вища за середню вартість предметів усередині.", "Кейсы открываются на странице «Кейси»: можно открывать 1–5 за раз, есть режим «Швидко». Точные шансы не публикуются: чем дороже скин, тем реже он выпадает, а цена кейса всегда выше средней стоимости предметов внутри.")
    if has(ws, "удач", "івент", "ивент", "event", "акці", "акци"):
        return R("Іноді діють івенти «x2 удача» — значок із таймером зʼявляється праворуч унизу. Слідкуйте за повідомленнями від адміністрації.", "Иногда действуют ивенты «x2 удача» — значок с таймером появляется справа внизу. Следите за сообщениями от администрации.")
    if has(ws, "інвентар", "инвентар"):
        return R(f"У вашому інвентарі {ctx.get('inv', 0)} предметів. Їх можна продати, вивести у Steam або використати в апгрейді.", f"В вашем инвентаре {ctx.get('inv', 0)} предметов. Их можно продать, вывести в Steam или использовать в апгрейде.")
    if has(ws, "нік", "ник", "nick", "аватар"):
        return R("Нік і аватар змінюються в «Профіль»: введіть новий нік і натисніть «Зберегти». Якщо потрібна допомога адміністрації — напишіть «змінити нік на …».", "Ник и аватар меняются в «Профіль»: введите новый ник и нажмите «Зберегти». Если нужна помощь администрации — напишите «изменить ник на …».")
    if has(ws, "правил", "угод", "соглашен", "вік", "возраст", "18", "легал", "закон"):
        return R("Сайт доступний тільки з 18 років. Монети та предмети віртуальні, виграш не гарантований. Повні умови показуються у вікні угоди під час входу через Steam.", "Сайт доступен только с 18 лет. Монеты и предметы виртуальные, выигрыш не гарантирован. Полные условия показываются в окне соглашения при входе через Steam.")
    if any(p in tl for p in ("як працю", "як це працю", "как работ", "как это работ", "що це", "що таке", "что это", "что такое", "розкажи", "расскаж")):
        return R("NeonDrop — відкриття кейсів із CS2-скінами та апгрейдер. Поповніть баланс, відкрийте кейс, виграний скін можна продати, вивести у Steam або підняти в апгрейді. Запитайте мене про поповнення, вивід, апгрейд чи промокоди.", "NeonDrop — открытие кейсов со скинами CS2 и апгрейдер. Пополните баланс, откройте кейс, выигранный скин можно продать, вывести в Steam или поднять в апгрейде. Спросите меня о пополнении, выводе, апгрейде или промокодах.")
    if has(ws, "дяку", "спасиб", "thanks", "благодар", "thx") and len(ws) <= 6: return R("Будь ласка! Якщо зʼявляться питання — пишіть.", "Пожалуйста! Если появятся вопросы — пишите.")
    if has(ws, "привіт", "привет", "здрав", "добрий", "добрый", "hello", "хай", "салют", "вітаю") and len(ws) <= 6:
        return R("Привіт! Я ШІ-помічник підтримки NeonDrop. Запитайте про поповнення, вивід скінів, апгрейд, промокоди чи баланс. Якщо потрібна людина — напишіть «адміністратор».", "Привет! Я ИИ-помощник поддержки NeonDrop. Спросите про пополнение, вывод скинов, апгрейд, промокоды или баланс. Если нужен человек — напишите «администратор».")
    if best[0] >= 0.45: return {"kind": "reply", "text": best[1]}
    # 5. не знаю → питаю адміністратора й вчуся з його відповіді
    return {"kind": "ask", "text": T(L, "Не впевнений, що правильно зрозумів питання, тому уточнюю в адміністрації — відповідь зʼявиться тут.", "Не уверен, что правильно понял вопрос, поэтому уточняю у администрации — ответ появится здесь.")}
